cssCode:
.marquee-wrap { height: 200vh; display: flex; align-items: center; overflow: hidden; }
.marquee-text {
  font-size: 60px; font-weight: 900; color: transparent;
  -webkit-text-stroke: 2px #00ffcc; white-space: nowrap;
  font-family: sans-serif;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;overflow-x:hidden;';

const wrap = document.createElement('div');
wrap.className = 'marquee-wrap';

const text = document.createElement('div');
text.className = 'marquee-text';
text.innerText = 'ULTRA MAX PREMIUM PRO SUPER ANIMATION • ULTRA MAX PREMIUM PRO • ';

wrap.appendChild(text);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const scrolled = c.scrollTop;
  text.style.transform = `translateX(-${scrolled * 1.2}px)`;
});
